function u(t){return new Date(t).toLocaleDateString("en-US",{year:"numeric",month:"short",day:"numeric"})}function c(t){return new Date(t).toLocaleDateString("en-US",{weekday:"long",year:"numeric",month:"long",day:"numeric"})}function f(t){const a=new Date,i=new Date(t),e=a.getTime()-i.getTime(),n=Math.floor(e/6e4),o=Math.floor(e/36e5),r=Math.floor(e/864e5);return n<1?"Just now":n<60?`${n}m ago`:o<24?`${o}h ago`:r<7?`${r}d ago`:u(t)}export{c as a,u as f,f as t};
